3	     3	/// The Assistant tab's transcript: a scroll view owning ONE non-editable,
4	     4	/// selectable text view (TextKit 1), the entries in order with one "\n"
5	     5	/// between them, so a selection and a plain-text copy cross entries (spec
6	     6	/// §11 AI-17). Each entry is a range of that text, kept in `spans`; a reply
7	     7	/// that is still extending edits only its own range. Scrolled to the newest
8	     8	/// line whenever an entry is appended or extended. It draws the transcript
9	     9	/// it is handed and keeps none of it (spec §11 AI-4: the entries are
10	    10	/// `EditorViewController.assistantTranscript`'s). Road map 12 A2.
11	    11	///
12	    12	/// One text view has no subview per entry, so the layout dump reads the
13	    13	/// entries as parts this view names (`UISnapshotParts`, dev only): the
14	    14	/// `assistant.entry.<kind>` records the proofs read.
15	    15	final class AssistantTranscriptView: NSScrollView {
16	    16	    private static let inset: CGFloat = 10
17	    17	    let textView: NSTextView
18	    18	    /// Each entry's kind and its UTF-16 range in the text, in order.
19	    19	    private var spans: [(kind: AssistantEntry.Kind, range: NSRange)] = []
20	    20	
21	    21	    init() {
22	    22	        textView = TranscriptTextView(usingTextLayoutManager: false)
23	    23	        super.init(frame: .zero)
24	    24	        hasVerticalScroller = true
25	    25	        autohidesScrollers = true
26	    26	        drawsBackground = false
27	    27	        borderType = .noBorder
28	    28	        textView.isEditable = false
29	    29	        textView.isSelectable = true
30	    30	        textView.drawsBackground = false
31	    31	        textView.isRichText = true
32	    32	        textView.textContainerInset = NSSize(width: Self.inset, height: 8)
33	    33	        textView.textContainer?.lineFragmentPadding = 0
34	    34	        textView.textContainer?.widthTracksTextView = true
35	    35	        textView.isVerticallyResizable = true
36	    36	        textView.isHorizontallyResizable = false
37	    37	        textView.minSize = .zero
38	    38	        textView.maxSize = NSSize(
39	    39	            width: CGFloat.greatestFiniteMagnitude, height: CGFloat.greatestFiniteMagnitude)
40	    40	        textView.autoresizingMask = [.width]
41	    41	        textView.frame = NSRect(origin: .zero, size: contentSize)
42	    42	        documentView = textView
43	    43	        // Adopting it runs the text view's `sizeToFit`, which leaves its
44	    44	        // origin at minus its new height (measured, #182); put it back at 0.
45	    45	        textView.setFrameOrigin(.zero)
46	    46	    }
47	    47	
48	    48	    @available(*, unavailable)
49	    49	    required init?(coder: NSCoder) {
50	    50	        fatalError("AssistantTranscriptView does not support NSCoder")
51	    51	    }
52	    52	
53	    53	    /// The text view is never shorter than the clip view, so a click below a
54	    54	    /// short transcript lands in the text (#182).
55	    55	    override func setFrameSize(_ newSize: NSSize) {
56	    56	        super.setFrameSize(newSize)
57	    57	        textView.minSize = NSSize(width: 0, height: contentSize.height)
58	    58	        textView.sizeToFit()
59	    59	    }
60	    60	
61	    61	    // MARK: - Drawing the transcript
62	    62	
63	    63	    func reload(_ entries: [AssistantEntry]) {
64	    64	        storage?.setAttributedString(NSAttributedString())
65	    65	        spans = []
66	    66	        for entry in entries { add(entry) }
67	    67	        scrollToNewest()
68	    68	    }
69	    69	
70	    70	    func apply(_ change: AssistantTranscriptChange) {
71	    71	        switch change {
72	    72	        case .appended(let entry):
73	    73	            add(entry)
74	    74	            scrollToNewest()
75	    75	        case .extended(let index, let text):
76	    76	            guard spans.indices.contains(index) else { return }
77	    77	            extend(index, to: text)
78	    78	            scrollToNewest()
79	    79	        case .cleared:
80	    80	            reload([])
81	    81	        case .usage, .conversationCost:
82	    82	            break
83	    83	        }
84	    84	    }
85	    85	
86	    86	    /// Each entry's kind, text and rect, in order, in THIS view's coordinates.
87	    87	    func entryLayout() -> [(kind: AssistantEntry.Kind, text: String, rect: NSRect)] {
88	    88	        guard let storage, let layout = textView.layoutManager,
89	    89	            let container = textView.textContainer
90	    90	        else { return [] }
91	    91	        layout.ensureLayout(for: container)
92	    92	        let origin = textView.textContainerOrigin
93	    93	        let text = storage.string as NSString
94	    94	        return spans.map { span in
95	    95	            let glyphs = layout.glyphRange(forCharacterRange: span.range, actualCharacterRange: nil)
96	    96	            var rect = layout.boundingRect(forGlyphRange: glyphs, in: container)
97	    97	            rect.origin.x += origin.x
98	    98	            rect.origin.y += origin.y
99	    99	            return (span.kind, text.substring(with: span.range), convert(rect, from: textView))
100	   100	        }
101	   101	    }
102	   102	
103	   103	    private var storage: NSTextStorage? { textView.textStorage }
104	   104	
105	   105	    private func add(_ entry: AssistantEntry) {
106	   106	        guard let storage else { return }
107	   107	        storage.beginEditing()
108	   108	        if !spans.isEmpty {
109	   109	            // The separator ends the previous entry's last paragraph, so it
110	   110	            // takes that paragraph's attributes.
111	   111	            let attributes = storage.length > 0
112	   112	                ? storage.attributes(at: storage.length - 1, effectiveRange: nil)
113	   113	                : Self.attributes(entry.kind, first: false, index: spans.count)
114	   114	            storage.append(NSAttributedString(string: "\n", attributes: attributes))
115	   115	        }
116	   116	        let start = storage.length
117	   117	        let styled = Self.styled(entry.text, entry.kind, index: spans.count)
118	   118	        storage.append(styled)
119	   119	        storage.endEditing()
120	   120	        spans.append((entry.kind, NSRange(location: start, length: styled.length)))
121	   121	    }
122	   122	
123	   123	    /// Entry `index`'s text is now `text`: only the new suffix is inserted
124	   124	    /// when the old text is a non-empty prefix of it; otherwise the entry's
125	   125	    /// range is replaced. The spans after it shift.
126	   126	    private func extend(_ index: Int, to text: String) {
127	   127	        guard let storage else { return }
128	   128	        let span = spans[index]
129	   129	        let old = (storage.string as NSString).substring(with: span.range)
130	   130	        let styled = Self.styled(text, span.kind, index: index)
131	   131	        let replaced: NSRange
132	   132	        let inserted: NSAttributedString
133	   133	        if !old.isEmpty, text.hasPrefix(old) {
134	   134	            let oldLength = (old as NSString).length
135	   135	            replaced = NSRange(location: NSMaxRange(span.range), length: 0)
136	   136	            inserted = styled.attributedSubstring(
137	   137	                from: NSRange(location: oldLength, length: styled.length - oldLength))
138	   138	        } else {
139	   139	            replaced = span.range
140	   140	            inserted = styled
141	   141	        }
142	   142	        guard replaced.length > 0 || inserted.length > 0 else { return }
143	   143	        storage.beginEditing()
144	   144	        storage.replaceCharacters(in: replaced, with: inserted)
145	   145	        storage.endEditing()
146	   146	        let delta = inserted.length - replaced.length
147	   147	        spans[index].range.length += delta
148	   148	        for later in spans.indices where later > index {
149	   149	            spans[later].range.location += delta
150	   150	        }
151	   151	    }
152	   152	
153	   153	    /// `text` in `kind`'s font and colour; its first paragraph carries the
154	   154	    /// gap above the entry, the rest none.
155	   155	    private static func styled(
156	   156	        _ text: String, _ kind: AssistantEntry.Kind, index: Int
157	   157	    ) -> NSAttributedString {
158	   158	        let result = NSMutableAttributedString(
159	   159	            string: text, attributes: attributes(kind, first: false, index: index))
160	   160	        let whole = text as NSString
161	   161	        let firstEnd = whole.paragraphRange(for: NSRange(location: 0, length: 0))
162	   162	        if firstEnd.length > 0 {
163	   163	            result.setAttributes(attributes(kind, first: true, index: index), range: firstEnd)
164	   164	        }
165	   165	        return result
166	   166	    }
167	   167	
168	   168	    /// The person's line opens a new exchange: a wider gap above it.
169	   169	    private static func attributes(
170	   170	        _ kind: AssistantEntry.Kind, first: Bool, index: Int
171	   171	    ) -> [NSAttributedString.Key: Any] {
172	   172	        let paragraph = NSMutableParagraphStyle()
173	   173	        paragraph.paragraphSpacingBefore = !first || index == 0 ? 0 : (kind == .person ? 14 : 6)
174	   174	        let font: NSFont
175	   175	        let colour: NSColor
176	   176	        switch kind {
177	   177	        case .person:
178	   178	            font = DS.sans(12, weight: .semibold)
179	   179	            colour = DS.textStrong
180	   180	        case .reply:
181	   181	            font = DS.sans(12)
182	   182	            colour = DS.textStrong
183	   183	        case .progress:
184	   184	            font = DS.sans(11)
185	   185	            colour = DS.textFaint
186	   186	        case .meta:
187	   187	            font = DS.mono(10)
188	   188	            colour = DS.textMuted
189	   189	        case .error:
190	   190	            font = DS.sans(11)
191	   191	            colour = DS.meterClip
192	   192	        }
193	   193	        return [.font: font, .foregroundColor: colour, .paragraphStyle: paragraph]
194	   194	    }
195	   195	
196	   196	    /// The newest line into view. The text view is flipped, so the end is
197	   197	    /// its full height less what the clip view shows.
198	   198	    private func scrollToNewest() {
199	   199	        layoutSubtreeIfNeeded()
200	   200	        if let layout = textView.layoutManager, let container = textView.textContainer {
201	   201	            layout.ensureLayout(for: container)
202	   202	        }
203	   203	        textView.sizeToFit()
204	   204	        let clip = contentView
205	   205	        let y = max(0, textView.frame.height - clip.bounds.height)
206	   206	        clip.scroll(to: NSPoint(x: 0, y: y))
207	   207	        reflectScrolledClipView(clip)
208	   208	    }
209	   209	}
210	   210	
211	   211	/// The transcript's text view: it copies plain text only. The type is the
212	   212	/// legacy string name NSTextView writes by (`writeSelection` answers false
213	   213	/// for `.string`, measured on macOS 26), which the pasteboard also offers as
214	   214	/// `public.utf8-plain-text`.
215	   215	private final class TranscriptTextView: NSTextView {
216	   216	    override var writablePasteboardTypes: [NSPasteboard.PasteboardType] {
217	   217	        [NSPasteboard.PasteboardType("NSStringPboardType")]
218	   218	    }
219	   219	}
220	   220	
221	   221	#if FRAMEJOB_DEV_TOOLS
222	   222	extension AssistantTranscriptView: UISnapshotParts {
223	   223	    /// One `assistant.entry.<kind>` part per entry, for the layout dump.
224	   224	    func snapshotParts() -> [UISnapshotPart] {
225	   225	        entryLayout().map { entry in
226	   226	            UISnapshotPart(
227	   227	                id: "assistant.entry.\(entry.kind.rawValue)", text: entry.text, rect: entry.rect)
228	   228	        }
229	   229	    }
230	   230	}
231	   231	#endif
232	     1	// The assistant helper: the agent loop, run by the Anthropic SDK's Tool
233	     2	// Runner, in a separate process the app launches from Contents/Helpers. It
234	     3	// speaks JSON lines over stdio (protocol.ts) and owns no tools itself: every
235	     4	// tool call goes back to the app, which runs it through the same dispatcher
236	     5	// its MCP server uses. Two apps carry agent/src/ byte for byte, Rasterize
237	     6	// and Frame Job: a change is one diff applied to both, and whatever differs
238	     7	// between them arrives in `configure`.
239	     8	
240	     9	import Anthropic from "@anthropic-ai/sdk";
241	    10	import type {
242	    11	  BetaMessage,
243	    12	  BetaTool,
244	    13	  BetaMessageParam,
245	    14	  BetaToolResultContentBlockParam,
246	    15	} from "@anthropic-ai/sdk/resources/beta/messages";
247	    16	import type { BetaRunnableTool } from "@anthropic-ai/sdk/lib/tools/BetaRunnableTool";
248	    17	import { ToolError } from "@anthropic-ai/sdk/lib/tools/ToolError";
249	    18	import { createInterface } from "node:readline";
250	    19	import { price } from "./pricing";
251	    20	import { initialPrices, refreshPrices } from "./priceTable";
252	    21	import type { LoadedPrices, PriceOptions } from "./priceTable";
253	    22	import type {
254	    23	  CallToolResult,
255	    24	  CatalogTool,
256	    25	  ChatSettings,
257	    26	  Configure,
258	    27	  HostMessage,
259	    28	  HelperEvent,
260	    29	} from "./protocol";
261	    30	
262	    31	/** Hard ceiling on API rounds within one turn. */
263	    32	const MAX_ITERATIONS = 30;
264	    33	/** Thinking counts toward this as well as the reply. */
265	    34	const MAX_TOKENS = 32000;
266	    35	
267	    36	const TOOL_SEARCH = {
268	    37	  type: "tool_search_tool_bm25_20251119",
269	    38	  name: "tool_search_tool_bm25",
270	    39	} as const;
271	    40	
272	    41	/**
273	    42	 * Old tool results are cleared, when the user turns it on, only past this
274	    43	 * many tokens in context and in chunks of at least CLEAR_AT_LEAST, so the
275	    44	 * prompt cache breaks rarely. The API applies it per request, so it can
276	    45	 * fire mid-turn; it never touches tool search results (server-side).
277	    46	 */
278	    47	const CLEAR_TRIGGER_TOKENS = 150_000;
279	    48	const CLEAR_AT_LEAST_TOKENS = 50_000;
280	    49	const CLEAR_KEEP_TOOL_USES = 5;
281	    50	
282	    51	/** Betas every request carries: progress notes, refusal fallback, and compaction blocks. */
283	    52	const BASE_BETAS = [
284	    53	  "thinking-display-updates-2026-08-18",
285	    54	  "server-side-fallback-2026-07-01",
286	    55	  "compact-2026-09-04",
287	    56	];
288	    57	
289	    58	let client: Anthropic | undefined;
290	    59	let config: Configure | undefined;
291	    60	/** Chat Settings; configure sets them and a settings message replaces them between turns. */
292	    61	let settings: ChatSettings = { auto_compact_tokens: 300_000, clear_tool_results: false };
293	    62	let tools: BetaRunnableTool[] = [];
294	    63	let history: BetaMessageParam[] = [];
295	    64	let turn: AbortController | undefined;
296	    65	let nextCallID = 0;
297	    66	/** Tokens in the conversation as of the last response, and the model's window. */
298	    67	let contextUsed = 0;
299	    68	let contextLimit: number | null = null;
300	    69	const pendingCalls = new Map<string, (result: CallToolResult | null) => void>();
301	    70	/** The price table in force; a turn takes it once, at its start (spec §11 P-5). */
302	    71	let prices: LoadedPrices | undefined;
303	    72	
304	    73	function emit(event: HelperEvent) {
305	    74	  process.stdout.write(JSON.stringify(event) + "\n");
306	    75	}
307	    76	
308	    77	function configure(message: Configure) {
309	    78	  config = message;
310	    79	  client = new Anthropic({
311	    80	    apiKey: message.api_key,
312	    81	    baseURL: message.api_base ?? "https://api.anthropic.com",
313	    82	    maxRetries: 3,
314	    83	  });
315	    84	  const core = new Set(message.core_tools);
316	    85	  tools = message.tools.map((entry) => runnableTool(entry, core));
317	    86	  settings = message.settings;
318	    87	  void lookUpContextLimit(message.model);
319	    88	  setUpPrices({ cache: message.price_cache, feed: message.price_feed });
320	    89	}
321	    90	
322	    91	/** The prices at `configure`: reported now when no refresh is due, else once
323	    92	 *  the refresh settles, in the same continuation that puts it in force. */
324	    93	function setUpPrices(options: PriceOptions) {
325	    94	  const initial = initialPrices(options);
326	    95	  prices = initial.prices;
327	    96	  if (!initial.refreshDue) {
328	    97	    emit({ type: "prices", source: initial.prices.source });
329	    98	    return;
330	    99	  }
331	   100	  void refreshPrices(initial.prices, options).then((loaded) => {
332	   101	    prices = loaded;
333	   102	    emit({ type: "prices", source: loaded.source });
334	   103	  });
335	   104	}
336	   105	
337	   106	/** What one response cost, at the prices its turn started with; `partial` for one cut short. */
338	   107	function emitCost(message: BetaMessage, turnPrices: LoadedPrices, partial?: true) {
339	   108	  emit({
340	   109	    type: "cost",
341	   110	    model: message.model,
342	   111	    usage: message.usage,
343	   112	    cost: price(message.usage, message.model, turnPrices.table),
344	   113	    prices: turnPrices.source,
345	   114	    ...(partial ? { partial } : {}),
346	   115	  });
347	   116	}
348	   117	
349	   118	/** The model's context window, from the Models API, for the panel's meter. */
350	   119	async function lookUpContextLimit(model: string) {
351	   120	  try {
352	   121	    const info = await client!.models.retrieve(model);
353	   122	    contextLimit = info.max_input_tokens ?? null;
354	   123	  } catch {
355	   124	    contextLimit = null; // the meter shows usage without a limit
356	   125	  }
357	   126	  emitContextUsage();
358	   127	}
359	   128	
360	   129	function emitContextUsage() {
361	   130	  emit({ type: "context_usage", used: contextUsed, limit: contextLimit });
362	   131	}
363	   132	
364	   133	/** Wraps one catalog entry: running it asks the app and waits for the answer. */
365	   134	function runnableTool(entry: CatalogTool, core: ReadonlySet<string>): BetaRunnableTool {
366	   135	  return {
367	   136	    name: entry.name,
368	   137	    description: entry.description,
369	   138	    input_schema: entry.inputSchema as BetaTool["input_schema"],
370	   139	    defer_loading: core.has(entry.name) ? undefined : true,
371	   140	    parse: (input: unknown) => input,
372	   141	    run: async (input: unknown) => {
373	   142	      emit({ type: "tool_call", name: entry.name, arguments: input });
374	   143	      const callID = String(++nextCallID);
375	   144	      const result = await new Promise<CallToolResult | null>((resolve) => {
376	   145	        pendingCalls.set(callID, resolve);
377	   146	        emit({ type: "tool_request", call_id: callID, name: entry.name, arguments_json: JSON.stringify(input) });
378	   147	      });
379	   148	      const { blocks, isError, summary } = convertToolResult(result);
380	   149	      emit({ type: "tool_result", name: entry.name, is_error: isError, summary });
381	   150	      if (isError) throw new ToolError(blocks);
382	   151	      return blocks;
383	   152	    },
384	   153	  };
385	   154	}
386	   155	
387	   156	/** MCP CallToolResult -> Messages API tool_result content, plus a one-line summary for the panel. */
388	   157	function convertToolResult(result: CallToolResult | null): {
389	   158	  blocks: BetaToolResultContentBlockParam[];
390	   159	  isError: boolean;
391	   160	  summary: string;
392	   161	} {
393	   162	  const failure = (message: string) => ({
394	   163	    blocks: [{ type: "text" as const, text: message }],
395	   164	    isError: true,
396	   165	    summary: message,
397	   166	  });
398	   167	  if (!result) return failure("The tool failed to execute.");
399	   168	  const blocks: BetaToolResultContentBlockParam[] = [];
400	   169	  let summary = "";
401	   170	  for (const item of result.content ?? []) {
402	   171	    if (item.type === "text") {
403	   172	      const text = item.text ?? "";
404	   173	      if (!summary) summary = text.slice(0, 200);
405	   174	      blocks.push({ type: "text", text });
406	   175	    } else if (item.type === "image") {
407	   176	      if (!summary) summary = "(image)";
408	   177	      blocks.push({
409	   178	        type: "image",
410	   179	        source: {
411	   180	          type: "base64",
412	   181	          media_type: (item.mimeType ?? "image/png") as "image/png",
413	   182	          data: item.data ?? "",
414	   183	        },
415	   184	      });
416	   185	    }
417	   186	  }
418	   187	  if (blocks.length === 0) return failure("The tool returned no content.");
419	   188	  return { blocks, isError: result.isError === true, summary };
420	   189	}
421	   190	
422	   191	/** Appends user text, merging into a trailing user message (e.g. cancelled tool results). */
423	   192	function pushUserText(text: string) {
424	   193	  const last = history.at(-1);
425	   194	  if (last?.role === "user") {
426	   195	    const content = typeof last.content === "string" ? [{ type: "text" as const, text: last.content }] : last.content;
427	   196	    last.content = [...content, { type: "text", text }];
428	   197	  } else {
429	   198	    history.push({ role: "user", content: [{ type: "text", text }] });
430	   199	  }
431	   200	}
432	   201	
433	   202	// History is append-only: nothing already sent is ever rewritten. Opus 5.5
434	   203	// replays its earlier thinking blocks only while everything before them is
435	   204	// byte-identical (and rejects the request outright on newer accounts), and
436	   205	// an unchanged prefix is also what keeps the prompt cache warm. Old canvas
437	   206	// renders therefore stay in history. The one sanctioned rewrite is the
438	   207	// API's own on-demand compaction, which swaps the history for its signed
439	   208	// summary block at the end of a turn (compactIfDue).
440	   209	
441	   210	/** Whether the conversation has outgrown the auto-compact limit. */
442	   211	function compactionDue(): boolean {
443	   212	  const limit = settings.auto_compact_tokens;
444	   213	  return limit !== null && contextUsed >= limit;
445	   214	}
446	   215	
447	   216	/** Tool result clearing, when on; see CLEAR_TRIGGER_TOKENS. */
448	   217	function contextManagement() {
449	   218	  if (!settings.clear_tool_results) return undefined;
450	   219	  return {
451	   220	    edits: [
452	   221	      {
453	   222	        type: "clear_tool_uses_20250919" as const,
454	   223	        trigger: { type: "input_tokens" as const, value: CLEAR_TRIGGER_TOKENS },
455	   224	        keep: { type: "tool_uses" as const, value: CLEAR_KEEP_TOOL_USES },
456	   225	        clear_at_least: { type: "input_tokens" as const, value: CLEAR_AT_LEAST_TOKENS },
457	   226	      },
458	   227	    ],
459	   228	  };
460	   229	}
461	   230	
462	   231	async function runTurn(text: string) {
463	   232	  if (!client || !config || !prices) {
464	   233	    emit({ type: "error", message: "The assistant helper was not configured." });
465	   234	    return;
466	   235	  }
467	   236	  if (turn) {
468	   237	    emit({ type: "error", message: "The assistant is busy." });
469	   238	    return;
470	   239	  }
471	   240	  const controller = new AbortController();
472	   241	  turn = controller;
473	   242	  const turnPrices = prices;
474	   243	  emit({ type: "turn_started" });
