  3	// MARK: - The agent lane: one lock around every tool call, from every caller
  4	
  5	/// The ask-first hook the assistant's session supplies (spec §11 AI-7): it is
  6	/// handed the question on the main thread and answers once, Allow (`true`) or
  7	/// Deny (`false`), from any thread.
  8	typealias AssistantAskFirst = (AssistantQuestion, @escaping (Bool) -> Void) -> Void
  9	
 10	/// Every tool call goes through here: the MCP trampoline (`serve`) and the
 11	/// assistant's session (`submit`). Road map 12 A1; spec §11 AI-2, AI-3, AI-5,
 12	/// AI-7 and AI-12.
 13	///
 14	/// **The lock.** One `NSLock` admits one call at a time, which is what keeps
 15	/// `AgentServer.callScope` and `callDocument` race-free now that there are two
 16	/// callers. It is never taken on main (AI-2): an `offMainTools` member holding
 17	/// it waits for main, so a main thread waiting on it would deadlock.
 18	/// `onMainWhenIdle` never locks, `submit` never blocks its caller, and nothing
 19	/// on main waits on the lane.
 20	///
 21	/// **The gesture wait (AI-12, #144).** A call that reaches main while any
 22	/// open document is mid-gesture waits for mouse-up, then runs: before this,
 23	/// a call run between two ticks of a drag answered ok and was then undone by
 24	/// the next tick. Every `onMain` hop is this wait, so it covers the off-main
 25	/// tools' hops too. Risk accepted: the call, and the lock with it, waits as
 26	/// long as the mouse is held down.
 27	///
 28	/// **The queues (#148).** `submit` runs on its document's serial queue, one
 29	/// per document with a call outstanding, so each window's calls are answered
 30	/// in order, its caller never waits, and a question pending in one window
 31	/// holds no other window's calls. `queuesLock` guards only the dictionary and
 32	/// is never held across a call, a wait or a completion; a document's queue is
 33	/// dropped once none of its calls is outstanding, so a new one is made only
 34	/// when there is nothing left to keep in order.
 35	final class AgentLane {
 36	    static let shared = AgentLane()
 37	
 38	    private let lock = NSLock()
 39	    private let queuesLock = NSLock()
 40	    private var queues: [ObjectIdentifier: LaneQueue] = [:]
 41	    private let server: AgentServer
 42	
 43	    /// The token of the `submit` call running now, nil in `serve` (spec §11
 44	    /// AI-16). Written only in `answer`, under `lock`, and cleared before it
 45	    /// is released, so a handler reads it on its own (lane) thread before any
 46	    /// `onMain` hop and links its own cancel with `onCancel`.
 47	    private(set) var callCancel: AgentCallCancel?
 48	
 49	    private init() {
 50	        server = AgentServer.shared
 51	    }
 52	
 53	    @available(*, unavailable) required init?(coder: NSCoder) {
 54	        fatalError("AgentLane does not support NSCoder")
 55	    }
 56	
 57	    // MARK: - Launch
 58	
 59	    /// The catalog, the gate and the parity check, once, from `main.swift`
 60	    /// before `NSApplicationMain` (AI-3): the assistant's calls need the gate
 61	    /// in a launch that never starts the MCP server.
 62	    static func prepareAtLaunch() {
 63	        do {
 64	            try AgentServer.shared.prepareCatalog()
 65	        } catch {
 66	            NSLog("Frame Job: %@", error.localizedDescription)
 67	        }
 68	    }
 69	
 70	    // MARK: - Callers
 71	
 72	    /// An MCP call, on the server thread, answered synchronously. It never
 73	    /// pins a document and never asks anyone anything (AI-7: an MCP caller is
 74	    /// never asked).
 75	    func serve(tool: String, argumentsJSON: String) -> String {
 76	        guard !Thread.isMainThread else {
 77	            // The core header says the server thread calls this, never main.
 78	            assertionFailure("AgentLane.serve was called on the main thread")
 79	            return server.execute(tool: tool, argumentsJSON: argumentsJSON)
 80	        }
 81	        lock.lock()
 82	        defer { lock.unlock() }
 83	        return route(tool, argumentsJSON)
 84	    }
 85	
 86	    /// An assistant call, pinned to `document` (AI-5). Returns at once;
 87	    /// `completion` runs exactly once, on `document`'s serial queue (#148).
 88	    /// A withheld tool is refused, and an ask-first one is put to `askFirst`
 89	    /// BEFORE the lock, so a pending question never holds up an MCP caller,
 90	    /// nor another document's calls. A call whose `cancel` is cancelled when
 91	    /// it takes the lock answers "Cancelled by the user." and never runs (AI-16).
 92	    func submit(
 93	        tool: String, argumentsJSON: String, document: ProjectDocument,
 94	        cancel: AgentCallCancel? = nil,
 95	        askFirst: @escaping AssistantAskFirst,
 96	        completion: @escaping (String) -> Void
 97	    ) {
 98	        let key = ObjectIdentifier(document)
 99	        enter(key).async { [self] in
100	            completion(answer(tool, argumentsJSON, document, cancel, askFirst))
101	            leave(key)
102	        }
103	    }
104	
105	    /// `key`'s queue, made on first use, with one more call outstanding.
106	    private func enter(_ key: ObjectIdentifier) -> DispatchQueue {
107	        queuesLock.lock()
108	        defer { queuesLock.unlock() }
109	        var entry =
110	            queues[key]
111	            ?? LaneQueue(
112	                queue: DispatchQueue(label: "com.kgalligan.framejob.agent-lane"), calls: 0)
113	        entry.calls += 1
114	        queues[key] = entry
115	        return entry.queue
116	    }
117	
118	    /// One call fewer outstanding on `key`'s queue; the entry is dropped at 0.
119	    private func leave(_ key: ObjectIdentifier) {
120	        queuesLock.lock()
121	        defer { queuesLock.unlock() }
122	        guard var entry = queues[key] else { return }
123	        entry.calls -= 1
124	        queues[key] = entry.calls > 0 ? entry : nil
125	    }
126	
127	    private func answer(
128	        _ tool: String, _ argumentsJSON: String, _ document: ProjectDocument,
129	        _ cancel: AgentCallCancel?, _ askFirst: @escaping AssistantAskFirst
130	    ) -> String {
131	        let arguments =
132	            (try? JSONSerialization.jsonObject(with: Data(argumentsJSON.utf8)))
133	            as? [String: Any] ?? [:]
134	        if let refusal = AssistantToolTable.refusal(tool: tool, arguments: arguments) {
135	            return errorResult(refusal)
136	        }
137	        if AssistantToolTable.row(for: tool)?.rule == .askFirst {
138	            let question = DispatchQueue.main.sync {
139	                AssistantToolTable.question(tool: tool, arguments: arguments, document: document)
140	            }
141	            if let question = question, !ask(question, askFirst) {
142	                return errorResult("The person declined: \(question.sentence).")
143	            }
144	        }
145	        lock.lock()
146	        defer { lock.unlock() }
147	        if cancel?.isCancelled == true { return AssistantSession.cancelledResult }
148	        callCancel = cancel
149	        defer { callCancel = nil }
150	        return server.pinning(document) { route(tool, argumentsJSON) }
151	    }
152	
153	    /// Puts `question` to the hook on main and waits for its answer here, on
154	    /// the document's queue, which holds only that document's calls (#148).
155	    /// The first answer counts.
156	    private func ask(_ question: AssistantQuestion, _ askFirst: @escaping AssistantAskFirst)
157	        -> Bool {
158	        let reply = LaneAnswer()
159	        DispatchQueue.main.async {
160	            askFirst(question) { allowed in reply.settle(allowed) }
161	        }
162	        return reply.wait()
163	    }
164	
165	    /// `execute` in place for an `offMainTools` member, else on main once no
166	    /// gesture is live. The caller holds the lock.
167	    private func route(_ tool: String, _ argumentsJSON: String) -> String {
168	        if AgentServer.offMainTools.contains(tool) {
169	            return server.execute(tool: tool, argumentsJSON: argumentsJSON)
170	        }
171	        return onMainWhenIdle { server.execute(tool: tool, argumentsJSON: argumentsJSON) }
172	    }
173	
174	    private func errorResult(_ message: String) -> String {
175	        let fallback = #"{"content":[{"type":"text","text":"tool failed"}],"isError":true}"#
176	        let content: [[String: Any]] = [["type": "text", "text": message]]
177	        return (try? server.callResult(content: content, isError: true)) ?? fallback
178	    }
179	
180	    /// `body` with the lock RELEASED, relocked in a `defer` before this
181	    /// returns. Its only callers are the two assistant dev tools, which
182	    /// `serve` runs under the lock on this thread: while one waits for a
183	    /// turn, the turn's own `submit` calls need the lock.
184	    func releasingLock<T>(_ body: () throws -> T) rethrows -> T {
185	        assert(!Thread.isMainThread)
186	        lock.unlock()
187	        defer { lock.lock() }
188	        return try body()
189	    }
190	
191	    // MARK: - The gesture wait (AI-12)
192	
193	    /// On main: `body` in place, with no gesture check, no `main.sync` and no
194	    /// sleep (what `onMain` always did there; a gesture can only end on main,
195	    /// so a wait here would never end). Off main: `body` on main once no open
196	    /// document is mid-gesture, retried every 20 ms with no bound. Never locks.
197	    func onMainWhenIdle<T>(_ body: () throws -> T) rethrows -> T {
198	        if Thread.isMainThread { return try body() }
199	        while true {
200	            let outcome: T? = try DispatchQueue.main.sync {
201	                Self.gestureInProgress() ? nil : try body()
202	            }
203	            if let outcome = outcome { return outcome }
204	            Thread.sleep(forTimeInterval: 0.02)
205	        }
206	    }
207	
208	    /// Main only: whether any open project is in a live gesture (a timeline,
209	    /// canvas or inspector-slider drag).
210	    static func gestureInProgress() -> Bool {
211	        assert(Thread.isMainThread)
212	        return AgentServer.shared.openProjects().contains { $0.isLiveEditing }
213	    }
214	}
215	
216	/// Stop's reach into the call it is running (spec §11 AI-16): the session
217	/// makes one per call and cancels it on Stop; the lane never starts a call
218	/// whose token is already cancelled, and a long-running handler links its own
219	/// cancel to it with `onCancel`. Only the first `cancel()` runs the handlers.
220	final class AgentCallCancel {
221	    private let lock = NSLock()
222	    private var cancelled = false
223	    private var handlers: [() -> Void] = []
224	
225	    init() {}
226	
227	    @available(*, unavailable) required init?(coder: NSCoder) {
228	        fatalError("AgentCallCancel does not support NSCoder")
229	    }
230	
231	    /// Any thread.
232	    var isCancelled: Bool {
233	        lock.lock()
234	        defer { lock.unlock() }
235	        return cancelled
236	    }
237	
238	    /// Main only. Idempotent; each handler runs once, outside the lock, here.
239	    func cancel() {
240	        assert(Thread.isMainThread)
241	        lock.lock()
242	        let run = cancelled ? [] : handlers
243	        cancelled = true
244	        handlers = []
245	        lock.unlock()
246	        run.forEach { $0() }
247	    }
248	
249	    /// Any thread. Already cancelled: `handler` runs at once, on this thread.
250	    func onCancel(_ handler: @escaping () -> Void) {
251	        lock.lock()
252	        guard !cancelled else {
253	            lock.unlock()
254	            handler()
255	            return
256	        }
257	        handlers.append(handler)
258	        lock.unlock()
259	    }
260	}
261	
262	/// The ask-first answer crossing from main (or wherever the hook replies) to
263	/// the document's queue on the lane. Only the first `settle` counts.
264	private final class LaneAnswer {
265	    private let lock = NSLock()
266	    private let semaphore = DispatchSemaphore(value: 0)
267	    private var value: Bool?
268	
269	    init() {}
270	
271	    @available(*, unavailable) required init?(coder: NSCoder) {
272	        fatalError("LaneAnswer does not support NSCoder")
273	    }
274	
275	    func settle(_ allowed: Bool) {
276	        lock.lock()
277	        let first = value == nil
278	        if first { value = allowed }
279	        lock.unlock()
280	        if first { semaphore.signal() }
281	    }
282	
283	    func wait() -> Bool {
284	        semaphore.wait()
285	        lock.lock()
286	        defer { lock.unlock() }
287	        return value ?? false
288	    }
289	}
