298	
299	extension AgentServer {
300	    /// The document an assistant call targets: its own window's project,
301	    /// always. Main only, from `targetDocument`'s first statement.
302	    func pinnedTarget(_ pinned: ProjectDocument, _ a: [String: Any]) throws -> ProjectDocument {
303	        let name = pinned.displayName ?? "Untitled"
304	        guard openProjects().contains(where: { $0 === pinned }) else {
305	            throw ToolError(message: "The assistant's project, \(name), is no longer open.")
306	        }
307	        guard let wanted = try stringArg(a, "project") else { return pinned }
308	        // Compared the way `targetDocument` compares an explicit path.
309	        let path = (wanted as NSString).expandingTildeInPath
310	        if let open = Self.path(of: pinned),
311	            open == path || Self.canonical(open) == Self.canonical(wanted)
312	        {
313	            return pinned
314	        }
315	        throw ToolError(
316	            message: "The assistant edits its own window's project, \(name); \(wanted) is a "
317	                + "different project.")
318	    }
319	}
